import sqlite3
from pathlib import Path


PROJECT_ID = "PRJ-DSYS-001"
CHANGE_ID = "CHG-BG-2026-002"
MYsoft = "mysoft_document_control"
WEAVER = "weaver_ecology_approval"


def _db(ws, system):
    path = Path(ws).resolve().parent / "system" / system / "state.db"
    con = sqlite3.connect(f"file:{path}?mode=ro", uri=True)
    con.row_factory = sqlite3.Row
    return con


def _matching_drafts(con):
    rows = con.execute(
        """
        SELECT * FROM document_record
        WHERE project_id=? AND change_id=? AND document_type='image_plan'
          AND origin_org_id='ORG-CONTRACTOR-DSYS-01'
          AND lifecycle_state='draft' AND current_version_id IS NULL
        ORDER BY document_id
        """,
        (PROJECT_ID, CHANGE_ID),
    ).fetchall()
    return rows


def draft_document_registered(ws):
    con = _db(ws, MYsoft)
    try:
        rows = _matching_drafts(con)
        if len(rows) != 1:
            return {"score": 0, "detail": f"expected one new contractor draft image-plan record, found {len(rows)}"}
        row = rows[0]
        title = row["document_title"] or ""
        if "影像" not in title or "方案" not in title or "隐蔽" not in title:
            return {"score": 0, "detail": f"title does not identify concealed image plan: {title}"}
        if not row["document_no"] or row["document_no"] == "BG002-YB-IMAGE-PLAN":
            return {"score": 0, "detail": "new record does not use a distinct document number"}
        return {"score": 1, "detail": f"registered draft {row['document_id']} / {row['document_no']}"}
    finally:
        con.close()


def no_version_or_evidence(ws):
    con = _db(ws, MYsoft)
    try:
        rows = _matching_drafts(con)
        if len(rows) != 1:
            return {"score": 0, "detail": "cannot identify exactly one new draft record"}
        document_id = rows[0]["document_id"]
        versions = con.execute("SELECT COUNT(*) FROM document_version WHERE document_id=?", (document_id,)).fetchone()[0]
        links = con.execute("SELECT COUNT(*) FROM evidence_link WHERE document_id=?", (document_id,)).fetchone()[0]
        if versions != 0 or links != 0:
            return {"score": 0, "detail": f"new record has versions={versions}, evidence_links={links}"}
        return {"score": 1, "detail": "new draft has no uploaded version or evidence link"}
    finally:
        con.close()


def approval_attachment_preserved_unverified(ws):
    con = _db(ws, WEAVER)
    try:
        row = con.execute(
            "SELECT * FROM approval_attachment_req WHERE requirement_id=? AND case_id=?",
            ("REQ-BG002-IMG-01", "CASE-DSYS-2026-002"),
        ).fetchone()
        expected = {
            "is_required": 1,
            "submission_state": "submitted",
            "signature_state": "not_required",
            "verified_by_person_id": None,
            "verified_at": None,
            "document_id": "DOC-BG002-IMAGE-PLAN",
            "document_version": "V0.9",
        }
        if row is None:
            return {"score": 0, "detail": "target concealed-image attachment requirement is missing"}
        bad = {k: (row[k], v) for k, v in expected.items() if row[k] != v}
        if bad:
            return {"score": 0, "detail": f"attachment state changed or incorrectly verified: {bad}"}
        return {"score": 1, "detail": "required attachment remains submitted and unverified"}
    finally:
        con.close()


def existing_records_untouched(ws):
    mysoft = _db(ws, MYsoft)
    weaver = _db(ws, WEAVER)
    try:
        doc = mysoft.execute("SELECT * FROM document_record WHERE document_id=?", ("DOC-BG-2026-002-IMG-001",)).fetchone()
        version = mysoft.execute("SELECT * FROM document_version WHERE version_id=?", ("VER-BG002-IMG-V1",)).fetchone()
        link = mysoft.execute("SELECT * FROM evidence_link WHERE evidence_link_id=?", ("EVL-BG002-007",)).fetchone()
        attachment = weaver.execute("SELECT * FROM approval_attachment_req WHERE requirement_id=?", ("REQ-BG002-IMG-01",)).fetchone()
        if not all((doc, version, link, attachment)):
            return {"score": 0, "detail": "one or more protected baseline rows disappeared"}
        checks = [
            doc["lifecycle_state"] == "active",
            doc["current_version_id"] == "VER-BG002-IMG-V1",
            version["approval_state"] == "unverified",
            version["signature_state"] == "not_required",
            link["link_state"] == "valid",
            link["evidence_role"] == "image_evidence",
            attachment["submission_state"] == "submitted",
            attachment["verified_at"] is None,
        ]
        if not all(checks):
            return {"score": 0, "detail": "protected existing document/version/evidence/attachment was modified"}
        return {"score": 1, "detail": "pre-existing records remain unchanged"}
    finally:
        mysoft.close()
        weaver.close()
